package com.company.platform.commerce.application;
import com.company.platform.commerce.domain.pricing.*; import com.company.platform.commerce.domain.product.*; import com.company.platform.commerce.domain.events.*; import com.company.platform.commerce.infrastructure.*; import org.springframework.stereotype.Service; import org.springframework.beans.factory.annotation.Autowired; import java.time.Instant; import java.util.*;
@Service public class PricingApplicationService { private final SellableProductRepository products; private final PriceRepository prices; private final TenantContextProvider tenant;
 private final KafkaCommerceEventPublisher events; @Autowired public PricingApplicationService(SellableProductRepository products,PriceRepository prices,TenantContextProvider tenant,KafkaCommerceEventPublisher events){this.products=products;this.prices=prices;this.tenant=tenant;this.events=events;}
 public SellableProduct enable(UUID marketplaceProductId,UUID storeId){var p=SellableProduct.create(tenant.currentTenantId(),marketplaceProductId,storeId);p.enable();var saved=products.save(p);events.publish(new CommerceEvent(UUID.randomUUID(),"SellableProductEnabled",saved.id(),saved.tenantId(),Instant.now(),saved));return saved;}
 public Price createPrice(UUID productId,Money money,Instant from,Instant until){var p=products.findByTenantIdAndId(tenant.currentTenantId(),productId).orElseThrow();if(p.status()!=SellableProductStatus.ENABLED)throw new IllegalStateException("product must be enabled");var saved=prices.save(Price.create(tenant.currentTenantId(),productId,money,from,until));events.publish(new CommerceEvent(UUID.randomUUID(),"PriceCreated",saved.id(),saved.tenantId(),Instant.now(),saved));return saved;}
 public Optional<Price> currentPrice(UUID productId){return prices.findActiveByTenantIdAndProductId(tenant.currentTenantId(),productId);}
}
